import{c as t,Q as o,j as a,m as r}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"Dual-Pool Token-Budget Routing for Cost-Efficient and Reliable LLM Serving","description":"","frontmatter":{"url":"https://arxiv.org/abs/2604.08075","title":"Dual-Pool Token-Budget Routing for Cost-Efficient and Reliable LLM Serving","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2604.08075,"authors":["Xunzhuo Liu","Bowei He","Xue Liu","Andy Luo","Haichen Zhang","Huamin Chen"],"domains":["cs.CL","token budget"],"html":"https://arxiv.org/html/2604.08075v1","pdf_path":"pdfs/2604.08075.pdf","published_date":"2026-04-09T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-04-09-dual-pool-token-budget-routing-2604-08075.md","filePath":"research/papers/2026-04-09-dual-pool-token-budget-routing-2604-08075.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-04-09-dual-pool-token-budget-routing-2604-08075.md"};function i(s,e,l,u,d,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="dual-pool-token-budget-routing-for-cost-efficient-and-reliable-llm-serving" tabindex="-1">Dual-Pool Token-Budget Routing for Cost-Efficient and Reliable LLM Serving <a class="header-anchor" href="#dual-pool-token-budget-routing-for-cost-efficient-and-reliable-llm-serving" aria-label="Permalink to &quot;Dual-Pool Token-Budget Routing for Cost-Efficient and Reliable LLM Serving&quot;">​</a></h1><p><strong>Authors</strong>: Xunzhuo Liu, Bowei He, Xue Liu, Andy Luo, Haichen Zhang, Huamin Chen <strong>Published</strong>: April 09, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2604.08075" target="_blank" rel="noreferrer">https://arxiv.org/abs/2604.08075</a> · <a href="https://arxiv.org/html/2604.08075v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2604.08075 <strong>Categories</strong>: cs.CL, token budget <strong>PDF</strong>: <a href="https://arxiv.org/abs/2604.08075" target="_blank" rel="noreferrer">research/papers/pdfs/2604.08075.pdf</a> (15 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Production vLLM fleets typically provision each instance for the worst-case context length, leading to substantial KV-cache over-allocation and under-utilized concurrency. In practice, 80-95% of requests are short, yet are served under configurations optimized for long contexts, wasting 4-8× throughput capacity and triggering reliability issues such as OOM crashes, preemption, and request rejections. We identify a common root cause for these inefficiencies: configuration-traffic mismatch. We propose dual-pool token-budget routing, a lightweight dispatch mechanism that partitions a homogeneous fleet into two specialized pools: a high-throughput short-context pool and a high-capacity long-context pool. Each request is routed based on its estimated total token budget, computed using a per-category bytes-to-token ratio that is learned online via exponential moving average from usage.prompt_tokens feedback, eliminating the need for a tokenizer. We also develop a simple analytical model that predicts fleet-level cost savings from workload characteristics and measured throughput differences, enabling practitioners to estimate benefits prior to deployment. Evaluations on real-world traces from the Azure LLM Inference Dataset and LMSYS-Chat-1M, serving Llama-3-70B on A100 GPUs, show that our approach reduces GPU-hours by 31-42%, corresponding to $2.86M annual savings at fleet scale, while lowering preemption rates by 5.4× and improving P99 TTFT by 6%. A case study with Qwen3-235B-A22B on AMD MI300X at 10,000 req/s projects $15.4M in annual savings. The method incurs only O(1) dispatch overhead, adapts automatically to heterogeneous workloads, and composes seamlessly with existing optimizations such as PagedAttention, continuous batching, and prefill-decode disaggregation.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>識別 production LLM fleet 的根本問題：<strong>configuration-traffic mismatch</strong>——80–95% 請求為短 context，卻在針對長 context 最佳化的實例上執行，造成 4–8× throughput 浪費與 OOM/preemption 可靠性問題。</li><li>提出 <strong>dual-pool token-budget routing</strong>：將同質 fleet 分成 short-context 高吞吐池與 long-context 高容量池，依每請求估算的 token budget 做 O(1) dispatch。</li><li>Token budget 估算採 <strong>per-category bytes-to-token ratio</strong>，透過 exponential moving average 從 <code>usage.prompt_tokens</code> 在線學習，完全不需 tokenizer，適合生產部署。</li><li>附帶 <strong>分析模型</strong>：根據 workload 特性與 throughput 差異預測 fleet 級省本，讓工程師部署前即可評估收益。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>Llama-3-70B on A100（Azure LLM Inference Dataset &amp; LMSYS-Chat-1M traces）：GPU-hours 減少 <strong>31–42%</strong>，換算年省 <strong>$2.86M</strong>。</li><li>Preemption rate 降低 <strong>5.4×</strong>；P99 TTFT 改善 <strong>6%</strong>。</li><li>Qwen3-235B-A22B on AMD MI300X（10,000 req/s）案例研究：年省預測 <strong>$15.4M</strong>。</li><li>與 PagedAttention、continuous batching、prefill-decode disaggregation 等現有優化無縫組合，無競態。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>文件未列獨立 limitation 章節。判斷弱點： <ul><li><strong>Pool 數量固定為 2</strong>：workload 若呈多峰分布（短、中、長混合），雙池切割可能不夠精細。</li><li><strong>bytes-to-token ratio 線上學習收斂期</strong>：冷啟動或 workload 突變初期，估算誤差可能導致路由偏差。</li><li><strong>評估模型受限</strong>：僅驗證 Llama-3-70B 與 Qwen3-235B；對 MoE 以外架構或多模態輸入的泛化性未驗證。</li></ul></li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>Token budget / context-management</strong>：論文的核心機制是依 token budget 做 routing，直接對應 <code>context-management.md</code> 中「Token Budget（軟性參考，防 loop 失控）」與「per-task ~4,000 / per-session ~30,000 tokens」監控概念——fleet 側的 budget-aware dispatch 與 agent 側的 budget 管理屬同一問題族。</li><li><strong>「判斷 vs 決定」跨切紀律</strong>：論文的 routing 邏輯（bytes-to-token ratio → pool 選擇）是純確定性計算，符合 <code>core.md</code> 跨切紀律「確定性代碼做決定（路由/重試）；LLM 做判斷」的設計原則，可作為 workspace subagent routing 設計的參照案例。</li><li><strong>Subagent fan-out 與 pool 分工</strong>：dual-pool 架構（short-context 高吞吐池 vs long-context 高容量池）概念上類似 <code>core.md §PROPOSE 委派</code>（原 <code>subagent-strategy.md</code>）的 model selection 按任務規模路由（0–1 檔 Haiku / 10+ 檔 Sonnet/Opus），提供 infrastructure 層驗證。</li><li>⚠️ 落地門檻：本論文針對 vLLM production fleet，workspace 目前無自建 inference fleet；概念可借鑒，但具體 pool 參數與 workload trace 分析不可直接套用。</li></ul>',16)])])}const p=t(n,[["render",i]]);export{h as __pageData,p as default};
